flex.on_mount:
const runHl = () => {
    if (typeof window === "undefined" || !window.hljs || !$el) return false;
    const codeEl = $el.querySelector('code');
    if (!codeEl) return false;
    delete codeEl.dataset.highlighted;
    window.hljs.highlightElement(codeEl);
    return true;
};
if (!runHl()) {
    let tries = 0;
    const timer = setInterval(() => {
        tries = tries + 1;
        if (runHl() || tries > 40) clearInterval(timer);
    }, 50);
}

const runHl = () => {
    if (typeof window === "undefined" || !window.hljs || !$el) return false;
    const codeEl = $el.querySelector('code');
    if (!codeEl) return false;
    delete codeEl.dataset.highlighted;
    window.hljs.highlightElement(codeEl);
    return true;
};
if (!runHl()) {
    let tries = 0;
    const timer = setInterval(() => {
        tries = tries + 1;
        if (runHl() || tries > 40) clearInterval(timer);
    }, 50);
}

const hl = () => {
    if (typeof window === "undefined" || typeof document === "undefined" || !$el) return true;
    if (!window.hljs) return false;
    $el.querySelectorAll('pre code').forEach((b) => {
        delete b.dataset.highlighted;
        window.hljs.highlightElement(b);
    });
    return true;
};
if (!hl()) {
    var _hl_attempts = 0;
    var _hl_timer = setInterval(function() {
        _hl_attempts = _hl_attempts + 1;
        if (hl() || _hl_attempts > 40) clearInterval(_hl_timer);
    }, 50);
}

flex.on_state_change:
setTimeout(() => {
    if (window.hljs && $el) {
        $el.querySelectorAll('pre code').forEach((b) => {
            delete b.dataset.highlighted;
            window.hljs.highlightElement(b);
        });
    }
}, 30);
